-- Offset pagination (page 3, 20 per page) — PostgreSQL / MySQL / SQLite
SELECT * FROM posts ORDER BY id LIMIT 20 OFFSET 40;

-- SQL Server
SELECT * FROM posts ORDER BY id OFFSET 40 ROWS FETCH NEXT 20 ROWS ONLY;

-- Keyset pagination: pass the last id you saw
SELECT * FROM posts WHERE id > :last_id ORDER BY id LIMIT 20;
